def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS-like approach with pruning to avoid cycles
    visited = [False] * n
    queue = deque()
    queue.append((s, 0))
    visited[s] = True

    while queue:
        u, dist = queue.popleft()

        for v, w in adj[u]:
