    if len(needle) > len(haystack):
        return -1

    # Preprocessing the needle to build a suffix automaton
    class State:
        def __init__(self):
            self.next = {}  # transitions
            self.link = -1  # suffix link
            self.len = 0    # length of the longest substring

    # Build the suffix automaton for the needle
    sa = [State()]
    last = 0

    for c in needle:
        curr = len(sa)
        sa.append(State())
        sa[curr].len = sa[last].len + 1
        p = last
        while p >= 0 and c not in sa[p].next:
            sa[p].next[c] = curr
            p = sa[p].link
        if p == -1:
            sa[curr].link = 0
        else:
            q = sa[p].next[c]
            if sa[p].len + 1 == sa[q].len:
                sa[curr].link = q
            else:
                clone = len(sa)
                sa.append(State())
                sa[clone].len = sa[p].len + 1
                sa[clone].next = sa[q].next.copy()
                sa[clone].link = sa[q].link
                while p >= 0 and sa[p].next[c] == q:
                    sa[p].next[c] = clone
                    p = sa[p].link
                sa[q].link = clone
                sa[curr].link = clone
        last = curr

    # Now check if the haystack matches the needle using the suffix automaton
    current = 0
    for i, c in enumerate(haystack):
        while current > 0 and c not in sa[current].next:
            current = sa[current].link
        if c in sa[current].next:
            current = sa[current].next[c]
        else:
            current = 0
        if sa[current].len == len(needle):
            return i - len(needle) + 1

    return -1

